; t07_timers -- the tick of the Main timer and of the Peri timer
; Layer-3 timing program (generated by conformance/make_timing.py: edit that, not this file).
; Markers are CSR writes to RES + k; the intervals between them are what is measured. Predictions: TIMING.md
.include "conf_defs.inc"
.include "conf_board.inc"                      ; the CSRs of the board: put YOUR addresses and bits there first
.main
.assume MAIN_SCRATCHPAD[0..31] defined
    EXEC_CSR WRITE8 MAIN_TPER,   20000 & 0xFF
    EXEC_CSR WRITE8 MAIN_TPER_H, 20000 >> 8
    EXEC_CSR WRITE8 RES + 0, 0x40            ; marker 0
    EXEC_CSR SET8 MAIN_CTRL, MAIN_TIMER_START
ma:
    BR.COND MAIN_TIMER_DONE, ma_d
    JMP ma
ma_d:
    EXEC_CSR WRITE8 RES + 1, 0x41            ; marker 1
    EXEC_CSR WRITE8 MAIN_TPER,   60000 & 0xFF
    EXEC_CSR WRITE8 MAIN_TPER_H, 60000 >> 8
    EXEC_CSR WRITE8 RES + 2, 0x42            ; marker 2
    EXEC_CSR SET8 MAIN_CTRL, MAIN_TIMER_START
mb:
    BR.COND MAIN_TIMER_DONE, mb_d
    JMP mb
mb_d:
    EXEC_CSR WRITE8 RES + 3, 0x43            ; marker 3
mhalt:
    JMP mhalt
.peri
.assume PERI_RX_BUF[0..31] defined
    EXEC_CSR SET8 PERI_CTRL, PERI_RESET
    EXEC_CSR WRITE8 PERI_TPER,   20000 & 0xFF
    EXEC_CSR WRITE8 PERI_TPER_H, 20000 >> 8
    EXEC_CSR WRITE8 RES + 16, 0x50            ; marker 16
    EXEC_CSR SET8 PERI_CTRL, PERI_TIMER_START
pa:
    BR.IF_TIMER_DONE pa_d
    JMP pa
pa_d:
    EXEC_CSR WRITE8 RES + 17, 0x51            ; marker 17
    EXEC_CSR WRITE8 PERI_TPER,   60000 & 0xFF
    EXEC_CSR WRITE8 PERI_TPER_H, 60000 >> 8
    EXEC_CSR WRITE8 RES + 18, 0x52            ; marker 18
    EXEC_CSR SET8 PERI_CTRL, PERI_TIMER_START
pb:
    BR.IF_TIMER_DONE pb_d
    JMP pb
pb_d:
    EXEC_CSR WRITE8 RES + 19, 0x53            ; marker 19
    EXEC_CSR SET8 PERI_CTRL, PERI_TIMER_START   ; one more wait, so that Main has finished too
pz:
    BR.IF_TIMER_DONE pz_d
    JMP pz
pz_d:
    EXEC_CSR WRITE8 RES_DONE, 0xA5
pdone:
    JMP pdone
